diff --git a/src/keys/rotate.ts b/src/keys/rotate.ts
index 90aa1f2..44be7d0 100644
--- a/src/keys/rotate.ts
+++ b/src/keys/rotate.ts
@@ -6,8 +6,16 @@ import { issueKey, revokeKey } from './store.js';

 export async function rotateApiKey(store: AuditStore, session: Session, keyId: string) {
   const next = await issueKey(keyId);
+  // Every rotation is recorded on the append-only audit log before the old
+  // key is revoked: who, what, when — replayable, hash-chained upstream.
+  appendEvent(store, {
+    type: 'key.rotate',
+    payload: { actor: session.userId, keyId, at: new Date().toISOString() },
+  });
   await revokeKey(keyId);
   return next;
 }
